def solve(expr):
    def operate(op, b, a):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def eval_expr(tokens):
        def apply_ops(ops, values):
            op = ops.pop()
            b = values.pop()
            a = values.pop()
            values.append(operate(op, b, a))

        ops, values = [], []
        i = 0
        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue
            if tokens[i] in ('+', '-', '*', '/'):
                while ops and precedence(ops[-1]) >= precedence(tokens[i]):
                    apply_ops(ops, values)
                ops.append(tokens[i])
            elif tokens[i] == '(':
                ops.append(tokens[i])
            elif tokens[i] == ')':
                while ops[-1] != '(':
                    apply_ops(ops, values)
                ops.pop()  # pop '('
            else:  # number
                j = i
                while j < len(tokens) and tokens[j].isdigit():
                    j += 1
                values.append(int(''.join(tokens[i:j])))
                i = j - 1
            i += 1

        while ops:
            apply_ops(ops, values)

        return values[0]

    # Remove spaces from input expression
    expr = expr.replace(" ", "")
    return eval_expr(expr)

# Example usage:
