def parse_duration(s):
    if not s:
        raise ValueError("Input string is empty.")

    total_seconds = 0
    unit_factors = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    last_unit = ''

    for i in range(len(s)):
        if s[i].isdigit():
            # Start of a number, check if previous was a valid unit
            if last_unit == '':
                raise ValueError(f"Number without a preceding unit at position {i}.")
        elif s[i] in unit_factors:
            # Start of a unit, check if previous was a valid number
            if not s[i - 1].isdigit() and i != 0:
                raise ValueError(f"Unit without a preceding number at position {i}.")

            current_unit = s[i]
            if current_unit in last_unit:
                raise ValueError(f"Repeated unit at position {i}.")

            # Convert the number before the unit to seconds and add to total
            number = int(s[i - 1].isdigit() and s[i - 1] or '1')  # Default to 1 if no number is provided
            total_seconds += number * unit_factors[current_unit]
            last_unit = current_unit
        else:
            raise ValueError(f"Unknown unit at position {i}.")

    if last_unit != 's':
        raise ValueError(f"Units are not in the correct order, last unit was {last_unit} at position {len(s) - 1}.")

    return total_seconds

