def parse_duration(s):
    if not s:
        raise ValueError("Input string is empty")

    unit_factors = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    last_unit = None
    total_seconds = 0

    i = 0
    while i < len(s):
        if s[i].isdigit():
            start = i
            while i < len(s) and s[i].isdigit():
                i += 1
            num = int(s[start:i])
            unit = s[i] if i < len(s) and s[i] in unit_factors else ''
            if not unit:
                raise ValueError(f"Number without a unit at position {start}")
            if unit not in unit_factors:
                raise ValueError(f"Unknown unit '{unit}'")
            if last_unit is not None and unit_factors[unit] < unit_factors[last_unit]:
                raise ValueError(f"Units out of order at position {start}")
            last_unit = unit
            total_seconds += num * unit_factors[unit]
            i += 1
        else:
            raise ValueError(f"Invalid character '{s[i]}' at position {i}")

    return total_seconds

# Example usage
