from collections import defaultdict, deque

def topo_sort(deps):
    # Reverse the dependency graph to get a graph where each node points to its parents
    reverse_deps = defaultdict(list)
    for task, depends_on in deps.items():
        for task_name in depends_on:
            reverse_deps[task_name].append(task)

    # Count the in-degrees of each node
    in_degree = {task: 0 for task in deps}
    for tasks in reverse_deps.values():
        for task in tasks:
            in_degree[task] += 1

    # Queue for tracking nodes with no dependencies
    queue = deque([task for task in in_degree if in_degree[task] == 0])
    topo_order = []

    while queue:
        # Always pop the smallest alphabetically
        task = min(queue)
        queue.remove(task)
        topo_order.append(task)

        for dependent in reverse_deps[task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    # Check for cycles
    if len(topo_order) != len(deps):
